    }

    if let Some(start) = line.find("http://") {
        let rest = &line[start..];
420→        let end = rest.find(char::is_whitespace).unwrap_or(rest.len());
        let url = &rest[..end];
        let url = url.trim_end_matches(|c| ['.', ',', ')', '"', '\''].contains(&c));
        return Some(url.to_string());
    }

